#include "support/process.hpp"
#include <sys/stat.h>
#include <set>
using namespace test;
int main(int argc,char** argv){try{check(argc==2,"nano executable required");std::string binary=argv[1];Temp root;Env env={{"NANO_PRIVATE_KEY",key()},{"NANO_WALLET_PASSWORD","test-only-password"}};
 auto command=[&](std::vector<std::string> args,bool ok=true,const Env& extra=Env{}){args.insert(args.begin(),{binary,"wallet"});auto effective=env;for(auto& [k,v]:extra)effective[k]=v;auto r=run(args,effective);check((r.code==0)==ok,r.err);check(r.out.find(key())==std::string::npos&&r.out.find("test-only-password")==std::string::npos&&r.err.find("test-only-password")==std::string::npos,"CLI exposed fixture secret");return ok?Json::parse(r.out):Json();};
 auto mode=[](const fs::path& p){struct stat s;check(stat(p.c_str(),&s)==0,"stat wallet");return s.st_mode&0777;};auto file=root/"wallet.json";
 check(command({"import",file.string()})["address"]==account&&mode(file)==0600,"import or permissions");check(command({"address",file.string()})["address"]==account,"wallet address");auto deployment=command({"deployment-address",file.string()})["contractAddress"];check(deployment=="0xf2e246bb76df876cef8b38ae84130f4f55de395b"&&command({"deployment-address",file.string(),"1"})["contractAddress"]!=deployment,"deployment nonce derivation");check(command({"sign-message",file.string(),"0x68656c6c6f"})["signature"].get<std::string>().size()==132,"message signature");auto original=read(file);command({"create",file.string()},false);check(read(file)==original,"existing wallet overwritten");command({"address",file.string()},false,{{"NANO_WALLET_PASSWORD","wrong"}});
 auto tx=root/"tx.json";save(tx,{{"to",account},{"nonce","0x0"},{"gas","0x5208"},{"gasPrice","0x3b9aca00"},{"chainId","0x539"}});auto signed_tx=command({"sign-transaction",file.string(),tx.string()});check(signed_tx["address"]==account&&signed_tx["hash"].get<std::string>().size()==66&&signed_tx["raw"].get<std::string>().starts_with("0x"),"transaction signing");save(tx,{{"from","0x"+std::string(40,'0')},{"to",account}});command({"sign-transaction",file.string(),tx.string()},false);
 auto vectors=load(fs::path(NANO_TEST_SOURCE)/"tests/fixtures/typed_data.json")["vectors"];auto typed=root/"typed.json";save(typed,vectors[0]["data"]);auto result=command({"sign-typed-data",file.string(),typed.string()});check(result["hash"]==vectors[0]["hash"]&&result["signature"]==vectors[0]["signature"],"typed signature");
 auto hd=load(fs::path(NANO_TEST_SOURCE)/"tests/fixtures/hdwallet.json")["vectors"][0];check(command({"hd-derive",(root/"derived.json").string(),"1"},true,{{"NANO_MNEMONIC",hd["mnemonic"].get<std::string>()}})["address"]==hd["children"][3]["address"],"HD derive vector");
 auto phrasefile=root/"mnemonic.json";auto generated=command({"hd-create",phrasefile.string(),"24"});std::string phrase=load(phrasefile)["mnemonic"];std::istringstream words(phrase);std::string word;unsigned count=0;while(words>>word)++count;check(count==24&&mode(phrasefile)==0600,"mnemonic size and permissions");check(command({"hd-derive",(root/"reproduced.json").string()},true,{{"NANO_MNEMONIC",phrase}})["address"]==generated["address"],"generated mnemonic round trip");command({"hd-create",phrasefile.string()},false);command({"hd-derive",(root/"invalid.json").string()},false,{{"NANO_MNEMONIC","abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon"}});
 auto directory=root/"accounts";auto batch=command({"create-many",directory.string(),"3"});check(batch.size()==3&&mode(directory)==0700,"batch count or permissions");std::set<std::string> unique;std::map<std::string,std::string> saved;for(unsigned i=0;i<batch.size();++i){auto item=batch[i];std::string path=item["keyfile"];unique.insert(item["address"]);check(item["index"]==i&&mode(path)==0600&&command({"address",path})["address"]==item["address"],"batch wallet integrity");saved[path]=read(path);}check(unique.size()==3,"batch uniqueness");command({"create-many",directory.string(),"3"},false);for(auto& [path,bytes]:saved)check(read(path)==bytes,"batch overwrite");check(command({"create-many",(root/"default").string()}).size()==10,"default wallet count");for(auto invalid:{"0","101","-1","abc"}){command({"create-many",(root/"invalid-accounts").string(),invalid},false);check(!fs::exists(root/"invalid-accounts"),"invalid batch created directory");}command({"create-many",(root/"no-password").string(),"2"},false,{{"NANO_WALLET_PASSWORD",std::nullopt}});check(!fs::exists(root/"no-password"),"missing password created directory");auto created=command({"create",(root/"new.json").string()});check(created["address"]==command({"address",(root/"new.json").string()})["address"],"new wallet unreadable");std::cout<<"Native wallet CLI scenarios passed\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
